pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 minSum, uint256 lockTime, uint256 stake, uint256 collectAmt) public {
        // Restrict amounts to reasonable range to avoid overflow/underflow in helper arithmetic and to keep domain wide
        vm.assume(minSum > 0 && minSum < type(uint128).max);
        vm.assume(stake > 0 && stake < type(uint128).max);
        vm.assume(collectAmt > 0 && collectAmt < type(uint128).max);
        vm.assume(lockTime < type(uint64).max);
        vm.assume(collectAmt <= stake && collectAmt <= minSum);

        // Deploy a re-entrant attacker that will call back into c.SetMinSum when receiving Ether from Collect
        Attacker attacker = new Attacker(c, 42);
        address attackerAddr = address(attacker);

        // Initialize the contract properly: set MinSum, set LogFile (harmless contract), mark initialized
        vm.prank(address(0x1));
        c.SetMinSum(minSum);
        vm.prank(address(0x1));
        c.SetLogFile(address(new LogHelper()));
        vm.prank(address(0x1));
        c.Initialized();

        // Fund attacker and have it Put Ether to create a withdrawable balance
        vm.deal(attackerAddr, stake);
        vm.prank(attackerAddr);
        c.Put{value: stake}(lockTime);

        // Warp past unlock time so Collect can proceed
        vm.warp(block.timestamp + lockTime + 1);

        // Record MinSum before the Collect call
        uint256 minSumBefore = c.MinSum();

        // Attempt Collect from attacker; this triggers reentrancy via attacker's receive()
        vm.prank(attackerAddr);
        try c.Collect(collectAmt) {} catch {}

        // After Collect finishes (or reverts), read MinSum again
        uint256 minSumAfter = c.MinSum();

        // The correct contract must keep MinSum unchanged after initialization;
        // the buggy contract allows SetMinSum to be called during reentrancy and change it.
        assertTrue(minSumBefore == minSumAfter);
    }
}

