        vm.warp(block.timestamp + lockTime + 1);

        // Attacker triggers Collect, which re-enters via receive to attempt reinitialization
        attacker.attack();

        // Assert that MinSum has NOT changed from its initial value
        assertTrue(c.MinSum() == minSumBefore);
    }
}

contract ReentrantAttacker {
    C public target;
    uint256 public balanceToCollect;
    bool private attacking;

    constructor(C _target, uint256 _balance) {
        target = _target;
        balanceToCollect = _balance;
        attacking = false;
    }

    function attack() external {
        // Re-entrancy guard for the attack itself
        require(!attacking, "already attacking");
        attacking = true;
        target.Collect(balanceToCollect);
        attacking = false;
    }

    receive() external payable {
        // Re-entrant call: try to reinitialize the contract via Initialized() + SetMinSum(0)
        // This only works if the modifier lacks the require check (buggy version).
        if (!attacking) {
            // Prevent infinite recursion
            attacking = true;
            try target.Initialized() {} catch {}
            try target.SetMinSum(0) {} catch {}
            attacking = false;
        }
    }
}

