pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address log1, address log2) public {
        // Ensure log1 and log2 are not the zero address
        vm.assume(log1 != address(0));
        vm.assume(log2 != address(0));
        // Deploy an adversarial Log contract that attempts re-entry during SetLogFile
        MaliciousLog malicious = new MaliciousLog(address(c), log2);
        // Initialize C
        vm.prank(actor);
        c.Initialized();
        // Attempt to set LogFile to the malicious contract; during its constructor or AddMessage call,
        // it will call SetLogFile again with log2.
        // The correct version (with modifier) will revert on re-entry; the buggy version allows it.
        bool ok;
        try c.SetLogFile(address(malicious)) {
            ok = true;
        } catch {
            ok = false;
        }
        // After the call(s), the resulting LogFile must equal the last argument supplied (log2)
        // if the buggy re-entry succeeds, or the call must have reverted (guarded).
        // The universal property: either the call reverts, or if it succeeds, LogFile must be the address passed to the outermost SetLogFile (i.e., address(malicious)).
        // In the buggy version, re-entry changes LogFile to log2 despite the outermost call passing malicious.
        // We assert: if the call succeeded, LogFile must equal address(malicious).
        assertTrue(!ok || address(c.LogFile()) == address(malicious));
    }
}

contract MaliciousLog {
    C public target;
    address public otherLog;
    constructor(address _target, address _otherLog) {
        target = C(_target);
        otherLog = _otherLog;
    }
    function AddMessage(address, uint, string memory) public {
        // On the first call to AddMessage (during SetLogFile after LogFile = Log(_log)),
        // we try to re-enter SetLogFile with a different address.
        target.SetLogFile(otherLog);
    }
}
